INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62209179', 62209179, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Procurement of Advanced Diagnostics & Treatment Systems', 'Barang', 'Tender', 'DKI Jakarta, Jakarta Selatan (Kota)', 27219440980, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 0, 0, '1 Paket', 'Procurement of Advanced Diagnostics & Treatment Systems Lot 1: Bronchoscopy System (4 unit) Lot 2: Opthalmoscope Indirect (12 unit) Lot 3: Vein Finder (6 unit) Lot 4: Continuous Renal Replacement Therapy (CRRT), Neonatal/Pediatric (2 unit) Lot 5: Laser Ophthalmic Diode Laser (6 unit) Lot 6: Automated Peritoneal Dialysis (14 unit)', 'Lot 1: Bronchoscopy System : Sistem endoskopi video multikomponen untuk semua jenis prosedur diagnostik dan terapeutik yang menggunakan endoskop fleksibel. Sistem endoskopi video memungkinkan tampilan gambar berwarna langsung dari bagian dalam tubuh selama prosedur endoskopi diagnostik dan terapeutik. Sistem ini juga memungkinkan gambar-gambar tersebut untuk disimpan, diambil, dan dimanipulasi secara elektronik ; Lot 2: Opthalmoscope Indirect : Oftalmoskop yang dikenakan di kepala dirancang untuk memeriksa mata (terutama bagian belakang mata, fundus) dengan memberikan gambar terbalik dari fundus. Instrumen ini biasanya terdiri dari sumber cahaya yang terpasang pada ikat kepala untuk memproyeksikan cahaya ke dalam mata melalui pupil dan lensa konvergen yang ditempatkan di depan mata pasien. ; Lot 3: Vein Finder : Alat pencari vena memancarkan cahaya inframerah (IR) atau inframerah dekat (NIR) melalui jaringan tubuh yang ditargetkan untuk menemukan dan menilai vena perifer secara non-invasif. Alat pencari vena memproyeksikan cahaya inframerah ke kulit pasien; cahaya inframerah diserap oleh sel darah merah dan dipantulkan oleh sel-sel lain, yang membantu membedakan vena dari jaringan sekitarnya ; Lot 4: Continuous Renal Replacement Therapy (CRRT), Neonatal/Pediatric : Unit hemodialisis dirancang untuk penggantian aktivitas utama ginjal secara terus-menerus dengan membuang air dan limbah secara perlahan dan stabil (yaitu, mesin terapi penggantian ginjal berkelanjutan [CRRT]) ; Lot 5: Laser Ophthalmic Diode Laser : Laser dioda, biasanya dioperasikan pada daya rendah dan dengan galium arsenida sebagai medium aktif pada panjang gelombang 810 nm, digunakan untuk mengkoagulasi jaringan pembuluh darah abnormal di retina dan untuk melakukan prosedur fotokoagulasi lainnya di mata ; Lot 6: Automated Peritoneal Dialysis : Perangkat yang dirancang untuk menghilangkan limbah metabolik melalui difusi selektif melintasi peritoneum dengan mengontrol aliran larutan yang dirancang khusus (yaitu, dialisat) ke dalam dan keluar dari rongga perut (yaitu, dialisis peritoneal). Perangkat ini terdiri dari mesin yang melakukan siklus dialisis otomatis, biasanya saat pasien tidur, dengan mengontrol aliran dialisat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 250519);
