INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62210147', 62210147, 'analyze_legacy', 'Pusat Pelaporan Dan Analisis Transaksi Keuangan', 'central', 'Pendidikan dan Pelatihan Anti Pencucian Uang PPATK', 'STP dan Pompa-pompa', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Barat, Depok (Kota)', 32000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, unit, @Rp32.000.000 )', '1. STP dan Pompa-pompa ( 1, unit, @Rp32.000.000 );', 'a. Spesifikasi Mutu 1) Memastikan pompa-pompa sampit, aerator, dan saluran pembuangan sampai dengan ke tangki pembuangan dapat bekerja dengan baik dan optimal; 2) Memastikan Tangki STP menghasilkan pembuangan yang merupakan limbah layak buang, dibuktikan dengan hasil analisis air; dan 3) Menyampaikan laporan pekerjaan setelah tiap kunjungan. b. Spesifikasi Layanan 1) Layanan emergency call 1x24 jam dengan 2 jam visit per emergency call; 2) Jaminan kualitas air buangan sesuai dengan peralatan yang terpasang; 3) Pemeliharaan sesuai dengan spesifikasi teknis yang ditetapkan; 4) Test and Commisioning; dan 5) General Check Up. Item Pemeliharaan a. Pembersihan field STP; b. Pembersihan dan pengangkatan sampah di bak sampit; c. Analisa air setiap 3 (tiga) bulan sekali; d. Perawatan peralatan STP (blower, pompa pipa, panel); e. Supply bakteri sesuai kebutuhan; f. Supply chlorine sesuai kebutuhan; g. Kunjungan teknisi sebanyak 1 (satu) kali setiap 2 (dua) minggu, dengan durasi tiap kunjungan selama min.1,5 jam atau sesuai kebutuhan; dan h. Membuat laporan pekerjaan (setiap kunjungan) dan hasil analisa air (setiap tiga bulan). Kegiatan: 22 visit (@2/bulan) Jangka Waktu: 11 Bulan (selama periode Februari s.d. Desember 2026)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 255634);
