INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62181856', 62181856, 'analyze_legacy', 'Kementerian Kelautan Dan Perikanan', 'central', 'PELABUHAN PERIKANAN NUSANTARA PENGAMBENGAN', 'Belanja Jasa Lainnya Pengelolaan Lingkungan Di Pelabuhan Perikanan', 'Jasa Lainnya', 'Pengadaan Langsung', 'Bali, Jembrana (Kab.)', 32350000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. Pengangkutan TPS oleh Dinas Lingkungan Hidup ( 12, BULAN, @ 1100000 ); 2. Biaya pengecekan kualitas air dan udara ( 4, PAKET, @ 4787500 );', 'Berikut adalah rincian spesifikasi pekerjaan untuk layanan kebersihan dan pengujian lingkungan: 1. Pengangkutan TPS oleh Dinas Lingkungan Hidup Durasi: 12 Bulan | Harga Satuan: Rp1.100.000/bulan Lingkup Pekerjaan: Pengangkutan sampah domestik dari Tempat Penampungan Sementara (TPS) di area kantor/pelabuhan menuju Tempat Pemrosesan Akhir (TPA). Frekuensi: Pengangkutan secara rutin (misal: 2-3 kali seminggu atau sesuai kesepakatan) untuk mencegah penumpukan sampah. Output: Area TPS yang bersih, bebas bau menyengat, dan terjaganya sanitasi lingkungan kerja. Administrasi: Pembayaran retribusi sampah bulanan kepada Dinas Lingkungan Hidup (DLH) setempat. 2. Biaya Pengecekan Kualitas Air dan Udara Jumlah: 4 Paket | Harga Satuan: Rp4.787.500/paket Mengingat ada 4 paket, pekerjaan ini biasanya dilakukan secara triwulanan (setiap 3 bulan sekali) sesuai standar ISO 14001:2015. Pengecekan Kualitas Air: Parameter: Uji laboratorium untuk air bersih atau air limbah (pH, BOD, COD, TSS, minyak & lemak). Lokasi: Pengambilan sampel pada titik outlet atau sumber air di lingkungan pelabuhan/kantor. Pengecekan Kualitas Udara: Parameter: Uji udara ambien (SO2, CO, NO2, O3, Debu/TSP) dan kebisingan. Lokasi: Titik-titik yang mewakili area kerja dan area publik. Output: Laporan Hasil Uji (LHU) resmi dari laboratorium yang terakreditasi KAN sebagai bukti kepatuhan terhadap regulasi lingkungan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 256481);
