INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62144197', 62144197, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Biaya Pemeliharaan Kendaraan Operasional Roda 2', 'Jasa Lainnya', 'Pengadaan Langsung', 'Kepulauan Riau, Tanjung Pinang (Kota)', 17850000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 7, PT, @ 2550000 )', '1. Biaya Pemeliharaan Kendaraan Operasional Roda 2 ( 7, PT, @ 255000 );', 'Pemeliharaan kendaraan operasional roda dua milik Balai Kekarantinaan Kesehatan Kelas I Tanjungpinang , meliputi jasa servis berkala dan penggantian suku cadang habis pakai sesuai standar pabrikan. Ruang lingkup pekerjaan mencakup pemeriksaan dan perawatan mesin, bahan bakar, sistem kelistrikan, sistem pengereman, penggantian oli mesin, busi, filter udara, serta penyetelan dan perbaikan ringan lainnya sesuai kebutuhan kendaraan. Pekerjaan dilaksanakan oleh bengkel resmi atau bengkel umum yang kompeten, menggunakan suku cadang yang sesuai standar mutu, dan dilaksanakan selama Tahun Anggaran 2026. Hasil pekerjaan harus menjamin kendaraan dalam kondisi laik jalan dan siap operasional.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 257718);
