INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62181220', 62181220, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN JASA KONSULTAN JUNIOR TEKNIS OPERASIONAL PENGELOLAAN SAMPAH KEGIATAN KOORDINASI REFORMASI PENGELOLAAN  PERSAMPAHAN TERINTEGRITAS DARI HULU KE HILIR 1', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 114180000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 0, 1, '12', '1. Mengidentifikasi dan analisis gap teknis operasional pengelolaan sampah di tingkat nasional dan daerah; 2. Melakukan perhitungan kebutuhan biaya operasional pengelolaan sampah dalam lingkup proyek/lokasi masing-masing di tingkat daerah; 3. Berkoordinasi dan komunikasi terkait teknis dan operasional pengelolaan sampah dengan instansi dan pihak terkait serta masing-masing pemerintah daerah; dan 4. Pelaksanaaan tugas lainnya terkait perencanaan teknis dan operasional pengelolaan sampah.', '1. Pendidikan minimal S1 bidang lingkungan (teknik lingkungan/infrastruktur lingkungan/rekayasa lingkungan/ilmu lingkungan/lainnya sejenis); 2. Diutamakan Tenaga ahli dalam negeri (dibuktikan dengan kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 3. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam bidang air minum / sanitasi / persampahan dalam kurun waktu 4 (empat) tahun terakhir baik dilingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak, dibuktikan dengan jumlah kontrak kerja/lama kontrak kerja; 4. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi atau karakteristik lainnya yang bisa menggambarkan kesamaan); 5. Memiliki pengalaman kerja minimal 3 (tiga) tahun dengan stakeholder pembangunan (pemerintah dan non-pemerintah) di sektor persampahan; 6. Memiliki pengalaman kerja minimal 1 (satu) tahun dalam kegiatan/pekerjaan yang berkaitan dengan sektor persampahan/sanitasi/air minum; dan 7. Memiliki kemampuan dalam menyusun laporan, kajian, maupun dokumen secara sistematis.; dan 8. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 257934);
