INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62181855', 62181855, 'analyze_legacy', 'Kementerian Kelautan Dan Perikanan', 'central', 'PELABUHAN PERIKANAN NUSANTARA PENGAMBENGAN', 'Belanja Jasa Lainnya Audit Sertifikasi ISO 14001:2015 dari PT QAI Indonesia', 'Jasa Lainnya', 'Pengadaan Langsung', 'Bali, Jembrana (Kab.)', 20000000, 'September 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. Audit Sertifikasi ISO 14001:2015 dari PT QAI Indonesia ( 1, Paket, @ 20000000 );', '1. Lingkup Pekerjaan (Scope of Work) Pekerjaan ini mencakup proses sertifikasi penuh atau audit surveilans (tergantung siklus sertifikasi Anda) yang terdiri dari: Audit Tahap 1 (Pre-Audit/Document Review): Peninjauan kesiapan dokumen, pemenuhan regulasi lingkungan, dan identifikasi aspek/dampak lingkungan penting. Audit Tahap 2 (Main Audit): Audit lapangan untuk memverifikasi implementasi sistem manajemen lingkungan di seluruh departemen terkait. Pelaporan: Pemberian laporan audit yang mencakup temuan kesesuaian, ketidaksesuaian (non-conformity), dan peluang perbaikan (opportunity for improvement). Penerbitan Sertifikat: Penerbitan sertifikat ISO 14001:2015 yang terakreditasi (misalnya oleh KAN) setelah dinyatakan lulus audit. 2. Parameter Audit Utama Lembaga audit akan memeriksa beberapa poin krusial, antara lain: Konteks Organisasi: Pemahaman isu internal/eksternal terkait lingkungan. Kepemimpinan: Komitmen manajemen puncak terhadap kebijakan lingkungan. Perencanaan: Penilaian risiko, peluang, dan tujuan lingkungan yang terukur. Operasional: Pengendalian limbah (B3/Non-B3), emisi, dan penggunaan sumber daya (energi/air). Evaluasi Kinerja: Audit internal dan tinjauan manajemen. 3. Output/Deliverables Vendor (PT QAI Indonesia) wajib menyediakan: Rencana Audit (Audit Plan). Laporan Audit resmi. Sertifikat ISO 14001:2015 (Masa berlaku biasanya 3 tahun dengan audit surveilans tahunan). Penggunaan Logo Sertifikasi untuk materi promosi/korespondensi perusahaan (sesuai aturan penggunaan logo). 4. Persyaratan Kompetensi Auditor Auditor harus memiliki sertifikat pelatihan Lead Auditor ISO 14001:2015. Memiliki pengalaman audit di sektor industri yang relevan (misalnya Kesyahbandaran/Maritim). Terdaftar secara resmi di bawah PT QAI Indonesia.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 258315);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62181426', 62181426, 'analyze_legacy', 'Kementerian Kelautan Dan Perikanan', 'central', 'PELABUHAN PERIKANAN NUSANTARA PENGAMBENGAN', 'Belanja Pemeliharaan Gedung dan Bangunan', 'Barang', 'Pengadaan Langsung', 'Bali, Jembrana (Kab.)', 74820000, 'May 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Pemeliharaan Gedung Kantor Permanen ( 172, M2, @ 145000 ); 2. pemeliharaan Bangunan Parkir Tertutup semi Permanen ( 172, m2, @ 145000 ); 3. Pemeliharaan Bangunan tempat ibadah permanen ( 172, M2, @ 145000 );', 'Spesifikasi Umum Pemeliharaan Bangunan 1. Pemeliharaan Gedung Kantor Permanen (172 m2) Fokus: Menjaga kenyamanan ruang kerja dan estetika bangunan. Pekerjaan Dinding: Pengecatan ulang dinding interior/eksterior yang kusam, pembersihan noda, serta perbaikan retak rambut pada plesteran. Pekerjaan Plafon: Pembersihan debu plafon, penggantian beberapa lembar plafon yang rusak/bercak air (jika ada kebocoran ringan), dan pengecatan list plafon. Pekerjaan Lantai: Pemolesan lantai keramik/granit dan perbaikan nat lantai yang lepas. Kelistrikan & Mekanikal: Pengecekan fungsi saklar, penggantian lampu yang mati, serta pembersihan unit AC (service cuci AC). Kusen & Jendela: Pelumasan engsel pintu/jendela dan pembersihan kaca secara menyeluruh. 2. Pemeliharaan Bangunan Parkir Tertutup Semi Permanen (172 m2) Fokus: Kekuatan struktur peneduh dan kebersihan area parkir. Struktur Atap: Pengecekan kebocoran pada atap (seng/spandek/asbes), pengencangan baut-baut baja ringan atau pembersihan karat pada tiang besi (jika ada). Pengecatan: Pengecatan ulang tiang penyangga dan marka/garis parkir agar terlihat jelas. Lantai/Lahan: Pembersihan lantai parkir dari ceceran oli, perbaikan bagian lantai yang retak, serta pembersihan saluran air (drainase) di sekitar area parkir agar tidak menggenang. Penerangan: Pengecekan dan penggantian lampu area parkir untuk keamanan di malam hari. 3. Pemeliharaan Bangunan Tempat Ibadah Permanen (172 m2) Fokus: Kebersihan, kesucian, dan kenyamanan jamaah. Pengecatan & Dinding: Pengecatan ulang dinding agar terlihat bersih dan suci, termasuk perbaikan detail arsitektur ringan. Fasilitas Wudhu: Perbaikan kran air yang bocor, pembersihan lumut pada lantai/dinding area wudhu, dan pembersihan saluran pembuangan. Lantai & Karpet: Pencucian karpet sajadah (vacuum/laundry) dan pembersihan lantai utama masjid/mushola. Sirkulasi Udara: Pembersihan kipas angin atau AC, serta pembersihan ventilasi agar udara tetap segar. Peralatan: Pengecekan sistem pengeras suara (sound system) sederhana.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 258316);
