INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62182530', 62182530, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR UPBU LAGALIGO', 'Penyusunan laporan RKL RPL', 'Jasa Konsultansi', 'Seleksi', 'Sulawesi Selatan, Luwu (Kab.)', 200000000, 'July 2026', 'APBN - PNBP (D)', 1, 1, '2 (Dua) Paket', 'Penyusunan laporan RKL RPL : a. Melaksanakan Rencana Pengelolaan lingkungan Hidup (RKL) dengan upaya kebijakan pengendalian dampak lingkungan berupa pencegahan, tindakan penanggulangan terhadap dampak negative yang mungkin terjadi , upaya pengembangan dampak positif dari pengembangan Bandar Udara Lagaligo. b. Melaksanakan Rencana Pemantauan Lingkungan Hidup (RPL) yakni pemantauan kondisi lingkungan , sehingga apabila terjadi penurunan kualitas lingkungan akibat kegiatan pengambangan dan pengoperasian Bandar Udara yang terjadi pada tahap prakonstruksi, kontruksi dan operasional dapat terdeteksi awal sehingga tindakan pengelolaan dapat diatasi. c) Melasanakan pelaporan RKL-RPL kepada instansi yang tercantum dalam izin lingkungan.', 'Penyusunan laporan RKL RPL : Metode pengumpulan dan analisa data harus relevan dengan metode pengumpulan dan analisa data untuk mengkaji zona lingkungan hidup untuk setiap dampak penting, yaitu : 1) Mencantumkan secara jelas metode yang digunakan dalam pengumpulan data berikut dengan jenis peralatan, instrumen dan tingkatan ketelitian alat yang digunakan dalam pengumpulan data yang digunakan harus sesuai dengan standar Nasional Indonesia (SNI), sesuai dengan peraturan perundang-undangan yang berlaku atau metode – metode ilmiah yang berlaku secara nasional dan internasional. 2) Uraikan metode yang digunakan untuk menganalisa data hasil pengukuran. Cantumkan jenis analisa data primer yang memerlukan pengujian laboratorium, maka harus dilakukan di laboratorium yang terakreditasi dan /atau teregristrasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 258508);
