INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62181836', 62181836, 'analyze_legacy', 'Kementerian Kelautan Dan Perikanan', 'central', 'PELABUHAN PERIKANAN NUSANTARA PENGAMBENGAN', 'Belanja Barang Persediaan Barang Konsumsi Pelayanan Pengusahaan pelabuhan perikanan', 'Barang', 'Pengadaan Langsung', 'Bali, Jembrana (Kab.)', 23278000, 'April 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. Form tagihan tambat labuh, karcis pas ( 1, PAKET, @ 23278000 );', '1. Form Tagihan Tambat Labuh Jenis Kertas: NCR (No Carbon Required) agar tulisan otomatis tembus ke rangkap di bawahnya. Rangkap: Minimal 3 atau 4 ply (Putih, Merah, Kuning, Biru). Ukuran: F4 (Folio) atau A4. Fitur Keamanan: * Numerator: Penomoran otomatis yang unik dan urut untuk setiap lembar formulir guna mencegah penggandaan ilegal dan memudahkan audit internal. Watermark/Logo: Cetak logo instansi sebagai identitas resmi dokumen PNBP. Finishing: Jilid blok lem atau perforasi (garis putus-putus) untuk memudahkan perobekan. 2. Karcis Pas (Masuk Pelabuhan/Kapal) Bahan: HVS 70/80 gr atau kertas khusus berserat (untuk keamanan tambahan). Model: Buku atau Blok (1 buku biasanya berisi 50 atau 100 lembar karcis). Fitur Validasi: Numerator: Nomor seri unik pada potongan karcis dan potongan arsip (porporasi). Perforasi: Garis lubang-lubang kecil agar karcis mudah disobek saat diberikan kepada pengguna jasa. Desain: Mencantumkan dasar hukum pemungutan, tarif sesuai aturan yang berlaku, dan logo resmi. 3. Ketentuan Umum Pekerjaan Kualitas Cetak: Tajam, tidak luntur, dan nomor urut tidak ada yang ganda/melompat. Packing: Dikemas per paket atau per dus secara rapi dan terlindung dari kelembapan. Volume: Mengingat nilai paket yang besar, pastikan jumlah buku/rim yang dipesan sesuai dengan kebutuhan operasional tahunan kantor.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 259171);
